create extension if not exists pgcrypto;
create table if not exists patient_profiles (id varchar(64) primary key,name text not null,home_state text default 'Assam',village_town text default '',language text default 'en',age int,family_members jsonb default '[]'::jsonb,former_occupation text default '',favorite_festival text default '',favorite_food text default '',clinical_notes text default '',dementia_stage text default 'mild',daily_routine jsonb default '{}'::jsonb,starting_difficulty_tier int default 3 check(starting_difficulty_tier between 1 and 10),mastery_score numeric default 0,game_mastery_scores jsonb default '{}'::jsonb,region_pack text default 'assam',active_cognitive_domains jsonb default '["attention","memory","executive"]'::jsonb,daily_cap int default 3 check(daily_cap between 1 and 5),pin text,is_active boolean default true,archive_reason text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists game_sessions (id uuid primary key default gen_random_uuid(),profile_id varchar(64) not null references patient_profiles(id) on delete cascade,game_type text not null,cognitive_domain text,difficulty_tier int,starting_level int,ending_level int,score numeric default 0,max_score numeric default 100,accuracy numeric,duration_seconds numeric default 0,error_count int default 0,response_time_ms numeric,mastery_before numeric,mastery_after numeric,dda_adjustment int default 0,metadata jsonb default '{}'::jsonb,completed_at timestamptz default now());
create table if not exists telemetry_logs (id uuid primary key default gen_random_uuid(),profile_id varchar(64) not null references patient_profiles(id) on delete cascade,session_id uuid,task_type text not null,latency_ms numeric,error_count int default 0,prosody_score numeric,dda_adjustment int default 0,alert_flag boolean default false,consecutive_errors int default 0,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists clinical_alerts (id uuid primary key default gen_random_uuid(),patient_id varchar(64) references patient_profiles(id) on delete cascade,severity text default 'attention',trigger_reason text not null,status text default 'open',acknowledged_by text,acknowledged_at timestamptz,visit_notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists family_members (id uuid primary key default gen_random_uuid(),patient_id varchar(64) references patient_profiles(id) on delete cascade,name text not null,relationship text not null,phone text,language text,created_at timestamptz default now());
create table if not exists family_memories (id uuid primary key default gen_random_uuid(),patient_id varchar(64) references patient_profiles(id) on delete cascade,title text not null,memory_type text default 'story',content jsonb default '{}'::jsonb,media_url text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists family_game_schedules (patient_id varchar(64) references patient_profiles(id) on delete cascade,pair text not null,weekday int not null,enabled boolean default true,primary key(patient_id,pair));
create table if not exists reminders (id uuid primary key default gen_random_uuid(),patient_id varchar(64) references patient_profiles(id) on delete cascade,title text not null,description text default '',time text not null,repeat_rule text default 'daily',enabled boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists sync_idempotency_records (client_event_id varchar(64) primary key,entity_type text not null,patient_id varchar(64),processed_at timestamptz default now());
create index if not exists idx_sessions_patient on game_sessions(profile_id,completed_at desc); create index if not exists idx_telemetry_patient on telemetry_logs(profile_id,created_at desc); create index if not exists idx_alerts_patient on clinical_alerts(patient_id,created_at desc); create index if not exists idx_reminders_patient on reminders(patient_id,time);
